class TrieNode: ch=[None]*26; cnt=0; end=False
class Trie:
  def insert(s):
    p = root
    for c in s:
      i = ord(c)-ord('a')
      if p.ch[i] is None: p.ch[i] = TrieNode()
      p = p.ch[i]; p.cnt += 1
    p.end = True
  def exists(s):
    p = walk(s)
    return p is not None and p.end
  def count_prefix(s): return walk(s).cnt if walk(s) else 0
